steps.seedCode:
const express = require('express');
const compression = require('compression');
const helmet = require('helmet');

const app = express();

// Use compression middleware here
app.use(compression());

// Use helmet middleware here
app.use(helmet());

// Define your GET route handler for '/' here
app.get('/', (req, res) => {
  res.send('Hello from Express with performance optimizations!');
});

// Add static file serving middleware here
app.use(express.static('public'));

// Add caching middleware here
app.use((req, res, next) => {
  res.set('Cache-Control', 'public, max-age=3600');
  next();
});

// Define your GET route handler for '/performance' here
app.get('/performance', (req, res) => {
  const memoryUsage = process.memoryUsage();
  res.json({
    message: 'Performance metrics',
    memoryUsage: memoryUsage
  });
});

// Start the server on port 3000 here
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

